INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`) VALUES
(975400, 'Mrrgl. Mrgl mrgl mrrrrgl.$B$B(The elder leans on his staff and watches the elves\' lights across the water.)', 'Mrrgl. Mrgl mrgl mrrrrgl.$B$B(The elder leans on his staff and watches the elves\' lights across the water.)', 1),
(975401, '(Grrmlgrrl doesn\'t look up from his spear. He grunts.)', '(Grrmlgrrl doesn\'t look up from his spear. He grunts.)', 1),
(975402, '(Murlorga offers you a ladle of something grey. It moves.)$B$BMrgl?', '(Murlorga offers you a ladle of something grey. It moves.)$B$BMrgl?', 1),
(975403, '(Blrrgl hides something behind his back, very fast.)$B$Bmrgl...', '(Blrrgl hides something behind his back, very fast.)$B$Bmrgl...', 1),
(975404, 'Mmmmrrrrgllll...$B$B(Oracle Glubbub stares straight through you, at something far out at sea.)', 'Mmmmrrrrgllll...$B$B(Oracle Glubbub stares straight through you, at something far out at sea.)', 1),
(975405, '(Mrrlglr slaps a fish on the counter and points at it, then at your coin pouch.)$B$BMrgl!', '(Mrrlglr slaps a fish on the counter and points at it, then at your coin pouch.)$B$BMrgl!', 1),
(975406, '(Sloshy hiccups.)', '(Sloshy hiccups.)', 1),
(975407, 'We were the Stormscale\'s, once, and before that Queen Azshara\'s. Now we are no one\'s but our own.$B$BThe night elves across the water have no reason to trust us. Give them one. And when they have taught you all they will, go south to the Grove of the Ancients: the old one there, Onu, hears what the sea says. He will know where your path goes next.', 'We were the Stormscale\'s, once, and before that Queen Azshara\'s. Now we are no one\'s but our own.$B$BThe night elves across the water have no reason to trust us. Give them one. And when they have taught you all they will, go south to the Grove of the Ancients: the old one there, Onu, hears what the sea says. He will know where your path goes next.', 1),
(975408, 'I watch the north. They will come from the north.', 'I watch the north. They will come from the north.', 1),
(975409, 'Coral, kelp, fresh water from the island\'s spring. It is not the palaces of Zin-Azshari. It will do.', 'Coral, kelp, fresh water from the island\'s spring. It is not the palaces of Zin-Azshari. It will do.', 1),
(975410, 'Keep your head down, mon. Dem Wrathtail got eyes all over dis beach.', 'Keep your head down, mon. Dem Wrathtail got eyes all over dis beach.', 1);
